(7498127, 1194734, 19825, '<td valign="top">Not what I was expecting, but it suits the challenge and I like the framing and repetition.</td>', 'Not what I was expecting, but it suits the challenge and I like the framing and repetition.', '2017-02-10 08:58:54.000000', NULL, 1),
